/**
 * DealFlow360 — Customer Quotation Store
 * Manages self-service customer created quotations with local storage persistence.
 */
import syncBus from './syncBus';

const STORAGE_KEY = 'dealflow_customer_quotations_v2';

const quoteListeners = new Set();

export function subscribeQuotations(listener) {
  quoteListeners.add(listener);
  return () => quoteListeners.delete(listener);
}

function notifyQuotationListeners() {
  quoteListeners.forEach((l) => {
    try {
      l();
    } catch (e) {
      console.error(e);
    }
  });
}

// Subscribe to real-time events on syncBus
syncBus.subscribe('quotes', (payload) => {
  try {
    if (payload?.quotes && Array.isArray(payload.quotes)) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(payload.quotes));
    } else if (payload?.quote && payload.quote.id) {
      const all = getAllQuotations();
      const idx = all.findIndex(q => q.id === payload.quote.id);
      if (idx >= 0) {
        if (payload.action === 'delete') {
          all.splice(idx, 1);
        } else {
          all[idx] = { ...all[idx], ...payload.quote };
        }
      } else if (payload.action !== 'delete') {
        all.unshift(payload.quote);
      }
      localStorage.setItem(STORAGE_KEY, JSON.stringify(all));
    }
  } catch (err) {
    console.error('[Customer QuotationStore] Error handling sync quote event:', err);
  }
  notifyQuotationListeners();
});
